import React, { Component } from 'react'
import {Dimensions, Image, Text, TouchableWithoutFeedback, View, Button, TouchableNativeFeedback, BackHandler} from 'react-native'
import styles from './TestStyles';
import SnapCarousel from 'react-native-snap-carousel';
import {NavigationActions, StackActions} from 'react-navigation';
import axios from "axios/index";
const screen = Dimensions.get('window');
  vh = screen.height / 100;
  vw = screen.width / 100;

class challengePerformance extends Component {

  static navigationOptions = ({ navigation }) => ({
    header : null
  })

  constructor() {
    super();
    this.handleBackButton = this.handleBackButton.bind(this);
    this.state = {
      your_total: 0,
      opponents_total: 0,
    }
  }

  componentWillUnmount() {
    BackHandler.removeEventListener('hardwareBackPress', this.handleBackButton);
  }

  handleBackButton() {
    
    this.props.navigation.dispatch(StackActions.popToTop());
    this.props.navigation.navigate('HomeStack', {}, NavigationActions.navigate({ routeName: 'Home' }));
    return true;
  }

  componentDidMount() {
    BackHandler.addEventListener('hardwareBackPress', this.handleBackButton);
   
    this.setState({your_total: this.props.navigation.state.params.answer.reduce(function(acc, val) { return acc + val; }, 0)});

    axios.get('https://classcast-198812.appspot.com/challenge/getchallengedata/'+this.props.navigation.state.params.challenge_id)
      .then(function (response){
        if(this.props.navigation.state.params.is_sender) {
          this.setState({opponents_total: response.data.receiver_marks})
        }
        else {
          this.setState({opponents_total: response.data.sender_marks})
        }
        
      }.bind(this))
      .catch(function (error) {
        
      });

    if(this.props.navigation.state.params.is_sender) {
      axios.post('https://classcast-198812.appspot.com/challenge/updateChallengeRequest', {
                            "completed_by_sender": true,
                            "challenge_id": this.props.navigation.state.params.challenge_id,
                            "sender_marks": this.props.navigation.state.params.answer.reduce(function(acc, val) { return acc + val; }, 0)
                          })
                      }
    else {
      axios.post('https://classcast-198812.appspot.com/challenge/updateChallengeRequest', {
                            "completed_by_receiver": true,
                            "challenge_id": this.props.navigation.state.params.challenge_id,
                            "receiver_marks": this.props.navigation.state.params.answer.reduce(function(acc, val) { return acc + val; }, 0)
                          })
    }

  }

  render() {
    
    return (
      <View style={styles.container}>
        <Image
          style={{
            position: 'absolute',
            flex: 1,
            width: '100%',
            height: '100%',
          }}
          source={{uri: 'data:image/png;base64,'}}
        />
            
             <View style={styles.challengeAcceptText1}>
                <View style={styles.playerStats}>
                  <Image
                    style={styles.profilePicture}
                    source={{uri: 'data:image/png;base64,'}}
                  />
                  <Text style={[styles.userName,{color: 'white'}]}>{'You'}</Text>
                  <View style={styles.statsFieldContainer}>
                    <Text style={[styles.focusText,{color: 'white'}]}>{this.state.your_total}</Text>
                    <Text style={[styles.notFocusText,{color: 'white'}]}>Points</Text>
                  </View>
                  
                </View>
                <View style={styles.playerStats}>
                  <Image
                    style={styles.profilePicture}
                    source={{uri: 'data:image/png;base64,'}}
                  />
                  <Text style={[styles.userName,{color: 'white'}]}>{this.props.navigation.state.params.opponent_name}</Text>
                  <View style={styles.statsFieldContainer}>
                    <Text style={[styles.focusText,{color: 'white'}]}>{this.state.opponents_total}</Text>
                    <Text style={[styles.notFocusText,{color: 'white'}]}>Points</Text>
                  </View>
                  
                </View>
              </View>
          <TouchableNativeFeedback
          onPress={() => {
            this.props.navigation.dispatch(StackActions.popToTop());
            this.props.navigation.navigate('HomeStack', {}, NavigationActions.navigate({ routeName: 'Home' }))
          }}
            >
          <View style={{position: 'absolute', marginTop: 87 * vh, height: 10 * vh, width: '100%', backgroundColor: 'indigo', justifyContent: 'center', alignItems: 'center'}}>
            <Text style={[styles.rightSplitText], {fontSize: 4 * vh, color: 'white' }}>Back to main menu</Text>
          </View>
          </TouchableNativeFeedback>
      </View>
    )
  }

}

export default challengePerformance
